const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Developer Workforce & Compensation Trends'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative accent bar top
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.08,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Developer Workforce &\nCompensation Trends", {
    x: 0.8, y: 1.2, w: 8.4, h: 2.0,
    fontSize: 40, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    lineSpacingMultiple: 1.2
  });

  // Subtitle - survey context
  slide.addText("2024 Stack Overflow Developer Survey", {
    x: 0.8, y: 3.2, w: 8.4, h: 0.5,
    fontSize: 22, fontFace: "Calibri",
    color: theme.accent, bold: false, align: "left"
  });

  // Key stat callout
  slide.addText("65,437 respondents across 180+ countries", {
    x: 0.8, y: 3.85, w: 8.4, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Source attribution
  slide.addText("Source: survey.stackoverflow.co/2024", {
    x: 0.8, y: 5.0, w: 5, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Decorative accent shape right side
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 9.2, y: 1.0, w: 0.12, h: 3.5,
    fill: { color: theme.accent }
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "d90429", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

