const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: '84% of Developers Are Working, but Full-Time Employment Dips in the U.S.'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.7,
    fontSize: 22, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    fit: "shrink"
  });

  // Divider line
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 1.0, w: 9, h: 0,
    line: { color: theme.secondary, width: 0.5 }
  });

  // Global stats - left column
  slide.addText("GLOBAL BREAKDOWN", {
    x: 0.5, y: 1.2, w: 4.2, h: 0.35,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "left", charSpacing: 2
  });

  // Stat callouts
  const stats = [
    { val: "69%", label: "Full-time employed" },
    { val: "16.4%", label: "Freelance / Contract" },
    { val: "13.2%", label: "Full-time students" }
  ];

  stats.forEach((s, i) => {
    const yPos = 1.65 + i * 1.1;
    slide.addText(s.val, {
      x: 0.5, y: yPos, w: 2, h: 0.6,
      fontSize: 36, fontFace: "Georgia",
      color: theme.accent, bold: true, align: "left", margin: 0
    });
    slide.addText(s.label, {
      x: 0.5, y: yPos + 0.55, w: 4, h: 0.3,
      fontSize: 14, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", margin: 0
    });
  });

