    x: 0.5, y: 1.0, w: 9, h: 0,
    line: { color: theme.secondary, width: 0.5 }
  });

  // 3-year trend chart using grouped bars
  const years = ["2022", "2023", "2024"];
  const categories = [
    { name: "Remote", values: [null, null, 38], color: theme.primary },
