const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'Senior Executives and Dev Advocates Top $124K+ Median Salary'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    fit: "shrink"
  });

  // Divider
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 0.9, w: 9, h: 0,
    line: { color: theme.secondary, width: 0.5 }
  });

  // Horizontal bar chart - top 10 roles by median salary
  const roles = [
    { name: "Senior Executive", salary: 127388 },
    { name: "Dev Advocate", salary: 124203 },
    { name: "Manager", salary: 115999 },
    { name: "Dev Experience", salary: 109483 },
    { name: "SRE", salary: 99099 },
    { name: "Cloud Infra. Engineer", salary: 96666 },
    { name: "Blockchain", salary: 85925 },
    { name: "Product Manager", salary: 80000 },
    { name: "Full-stack", salary: 63333 },
    { name: "Front-end", salary: 48787 }
  ];

  const maxSalary = 127388;
  const barMaxWidth = 4.5;
  const startY = 1.1;
  const barHeight = 0.32;
  const barGap = 0.1;

  roles.forEach((role, i) => {
    const yPos = startY + i * (barHeight + barGap);
    const barWidth = (role.salary / maxSalary) * barMaxWidth;
    const barColor = i < 3 ? theme.accent : theme.primary;

    // Role label
    slide.addText(role.name, {
      x: 0.5, y: yPos, w: 2.4, h: barHeight,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "right", valign: "middle", margin: 0
    });

    // Bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 3.0, y: yPos + 0.04, w: barWidth, h: barHeight - 0.08,
      fill: { color: barColor }
    });

    // Value label
    slide.addText("$" + (role.salary / 1000).toFixed(0) + "K", {
      x: 3.0 + barWidth + 0.1, y: yPos, w: 0.8, h: barHeight,
      fontSize: 10, fontFace: "Calibri",
      color: barColor, bold: true, align: "left", valign: "middle", margin: 0
    });
  });

  // Right side - figure image reference
  slide.addImage({
    path: "./imgs/figure_1.jpg",
    x: 7.8, y: 1.1, w: 1.8, h: 3.0,
    sizing: { type: "contain", w: 1.8, h: 3.0 }
  });

  // Key insight
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 5.0, w: 7, h: 0.02,
    fill: { color: theme.secondary }
  });
  slide.addText("22,677 salary responses (34.7% response rate) | SRE and Cloud Infra are highest-paid purely technical roles", {
    x: 0.5, y: 5.05, w: 8.5, h: 0.35,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "d90429", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

