const slideConfig = {
  type: 'content',
  index: 7,
  title: '47% Work at Sub-100 Orgs; 62% Influence Tech Purchases'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 20, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left",
    fit: "shrink"
  });

  // Divider
  slide.addShape(pres.shapes.LINE, {
    x: 0.5, y: 0.9, w: 9, h: 0,
    line: { color: theme.secondary, width: 0.5 }
  });

  // LEFT SIDE - Company Size Distribution
  slide.addText("COMPANY SIZE DISTRIBUTION", {
    x: 0.5, y: 1.15, w: 4.5, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "left", charSpacing: 2
  });

  const sizes = [
    { label: "Freelancer/solo", pct: 6.1 },
    { label: "2-9", pct: 10.4 },
    { label: "10-19", pct: 8.9 },
    { label: "20-99", pct: 21.2 },
    { label: "100-499", pct: 18.5 },
    { label: "500-999", pct: 6.7 },
    { label: "1,000-4,999", pct: 11.0 },
    { label: "5,000-9,999", pct: 3.8 },
    { label: "10,000+", pct: 11.4 }
  ];

  const maxPct = 21.2;
  sizes.forEach((s, i) => {
    const yPos = 1.55 + i * 0.38;
    const barW = (s.pct / maxPct) * 2.5;
    const isHighlight = s.pct > 15;

    slide.addText(s.label, {
      x: 0.5, y: yPos, w: 1.5, h: 0.32,
      fontSize: 9, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "right", valign: "middle", margin: 0
    });
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 2.1, y: yPos + 0.06, w: barW, h: 0.2,
      fill: { color: isHighlight ? theme.accent : theme.primary }
    });
    slide.addText(s.pct + "%", {
      x: 2.1 + barW + 0.08, y: yPos, w: 0.6, h: 0.32,
      fontSize: 9, fontFace: "Calibri",
      color: isHighlight ? theme.accent : theme.primary, bold: isHighlight, align: "left", valign: "middle", margin: 0
    });
  });

  slide.addText("n = 42,827 respondents", {
    x: 0.5, y: 5.05, w: 3, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Vertical divider
  slide.addShape(pres.shapes.LINE, {
    x: 5.0, y: 1.1, w: 0, h: 4.0,
    line: { color: theme.secondary, width: 0.5 }
  });

  // RIGHT SIDE - Purchasing Influence
  slide.addText("TECHNOLOGY PURCHASING INFLUENCE", {
    x: 5.3, y: 1.15, w: 4.2, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "left", charSpacing: 2
  });

  // Big stat
  slide.addText("62%", {
    x: 5.3, y: 1.55, w: 2.5, h: 0.9,
    fontSize: 52, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", margin: 0
  });
  slide.addText("of developers influence\ntech purchases", {
    x: 7.5, y: 1.7, w: 2.2, h: 0.7,
    fontSize: 13, fontFace: "Calibri",
    color: theme.primary, bold: false, align: "left"
  });

  // Influence by role
  slide.addText("INFLUENCE BY ROLE", {
    x: 5.3, y: 2.7, w: 4, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "left", charSpacing: 2
  });

  const roles = [
    { role: "Senior Executives", pct: "99%" },
    { role: "Engineering Managers", pct: "87%" },
    { role: "Product Managers", pct: "77%" }
  ];

  roles.forEach((r, i) => {
    slide.addText(r.role, {
      x: 5.3, y: 3.05 + i * 0.4, w: 2.5, h: 0.35,
      fontSize: 12, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
    slide.addText(r.pct, {
      x: 8.2, y: 3.05 + i * 0.4, w: 0.8, h: 0.35,
      fontSize: 12, fontFace: "Calibri",
      color: theme.accent, bold: true, align: "right", valign: "middle", margin: 0
    });
  });

  // Evaluation methods
  slide.addText("HOW DEVELOPERS EVALUATE TOOLS", {
    x: 5.3, y: 4.35, w: 4, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: true, align: "left", charSpacing: 2
  });

  slide.addText([
    { text: "75% start a free trial", options: { breakLine: true } },
    { text: "73% ask other developers", options: { breakLine: true } },
    { text: "60% prefer build-and-buy approach" }
  ], {
    x: 5.3, y: 4.65, w: 4, h: 0.9,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: false, align: "left",
    bullet: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "d90429", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-07-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

