const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'summary',
  index: 8,
  title: 'Takeaways: What These Trends Mean for Hiring & Retention'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Title
  slide.addText(slideConfig.title, {
    x: 0.6, y: 0.4, w: 8.8, h: 0.7,
    fontSize: 24, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left"
  });

  // Accent bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.1, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Takeaway items
  const takeaways = [
    {
      num: "01",
      title: "Plan for more contractors",
      desc: "Full-time employment is softening (U.S. dropped 4pp YoY). Build workforce models that accommodate 16%+ freelancers and contractors."
    },
    {
      num: "02",
      title: "Hybrid remains dominant, but in-person is growing",
      desc: "In-person mandates now at 20% (up from 15% in 2022). Hybrid at 42% is still the norm — forced RTO risks attrition."
    },
    {
      num: "03",
      title: "DevRel and SRE roles command premium pay",
      desc: "Dev Advocates ($124K) and SREs ($99K) reflect market scarcity. Budget accordingly for these hard-to-fill roles."
    },
    {
      num: "04",
      title: "Language choice correlates with compensation",
      desc: "Niche functional languages (Erlang, Clojure, Elixir) pay >$93K median. Mainstream (JS, PHP) sit below $65K."
    },
    {
      num: "05",
      title: "Engage developers directly in purchasing",
      desc: "62% of developers influence tech purchases. Vendor strategies should target ICs, not just management — trials and peer reviews win."
    }
  ];

  takeaways.forEach((t, i) => {
    const yPos = 1.35 + i * 0.82;

    // Number
    slide.addText(t.num, {
      x: 0.6, y: yPos, w: 0.5, h: 0.4,
      fontSize: 16, fontFace: "Georgia",
      color: theme.accent, bold: true, align: "left", valign: "top", margin: 0
    });

    // Title
    slide.addText(t.title, {
      x: 1.2, y: yPos, w: 8.2, h: 0.32,
      fontSize: 14, fontFace: "Calibri",
      color: "FFFFFF", bold: true, align: "left", valign: "middle", margin: 0
    });

    // Description
    slide.addText(t.desc, {
      x: 1.2, y: yPos + 0.34, w: 8.2, h: 0.42,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "left", valign: "top", margin: 0
    });
  });

  // Source
  slide.addText("Source: 2024 Stack Overflow Developer Survey | survey.stackoverflow.co/2024", {
    x: 0.6, y: 5.2, w: 6, h: 0.25,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left"
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "2b2d42", secondary: "8d99ae", accent: "ef233c", light: "d90429", bg: "edf2f4" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

